// @ts-nocheck
// ===== Relay ระดับน้ำ 3 ตัว → 4 ระดับ =====
//   Relay1 = EMPTY (DI1) · Relay2 = MID (DI2) · Relay3 = FULL (DI3)
//   R1 ติด  R2 ติด  R3 ติด  = full   (เต็ม)
//   R1 ติด  R2 ติด  R3 ดับ  = normal (ปกติ)
//   R1 ติด  R2 ดับ  R3 ดับ  = low    (ใกล้หมด)
//   R1 ดับ  R2 ดับ  R3 ดับ  = empty  (หมด)
//   แบบอื่น (เช่น R3 ติด แต่ R2 ดับ)  = fault  (Relay/สายผิดปกติ)
// ส่งไป WaterTank.aspx เมื่อระดับเปลี่ยน (ต้องนิ่ง STABLE_MS ก่อน) + ส่งซ้ำทุก HEARTBEAT_MS ให้หน้าเว็บรู้ว่ายังออนไลน์
// ===================== ตั้งค่า =====================
const TANK = "Water1";
const DI_EMPTY = 1;         // Relay1 EMPTY ต่อเข้า DI ช่องไหน
const DI_MID = 2;           // Relay2 MID
const DI_FULL = 3;          // Relay3 FULL
const INVERT = false;       // true = ใช้หน้าสัมผัส NC (Relay ติด แต่ DI ดับ) · ถ้าหน้าเว็บแสดงกลับด้าน ให้เปลี่ยนตรงนี้
const STABLE_MS = 10000;    // ค่าต้องเหมือนเดิมต่อเนื่อง 10 วิ ถึงจะยอมเปลี่ยนระดับ (กันน้ำกระเพื่อม)
const HEARTBEAT_MS = 60000; // ส่งสถานะซ้ำทุก 60 วิ
// ==================================================

function truthy(v) {
    if (v === null || v === undefined) return null;
    if (typeof v === "boolean") return v;
    if (typeof v === "number") return v !== 0;
    const s = String(v).trim().toLowerCase();
    if (["1", "true", "on", "high"].includes(s)) return true;
    if (["0", "false", "off", "low"].includes(s)) return false;
    return null;
}
// รองรับหลายรูปแบบจาก digital-input-all : {DI1:1,...} / {di1:true} / [1,0,0,0] / ตัวเลขบิต / msg.DI1
function pick(m, n) {
    const p = m.payload; let v;
    if (Array.isArray(p)) v = p[n - 1];
    else if (p && typeof p === "object") {
        for (const k of ["DI" + n, "di" + n, "Di" + n, "DI_" + n, "di_" + n, "input" + n, "IN" + n, String(n)])
            if (p[k] !== undefined) { v = p[k]; break; }
        if (v && typeof v === "object") v = v.value ?? v.state ?? v.status;
    }
    else if (typeof p === "number" && Number.isInteger(p)) v = (p >> (n - 1)) & 1;   // bitmask
    if (v === undefined && m["DI" + n] !== undefined) v = m["DI" + n];
    return truthy(v);
}
const TH = { full: "เต็ม", normal: "ปกติ", low: "ใกล้หมด", empty: "หมด", fault: "ผิดปกติ" };
const headers = { "Content-Type": "application/json" };

// ปุ่มทดสอบ (ไม่ส่ง LINE)
if (msg.sim) {
    const di = { full: [1, 1, 1], normal: [1, 1, 0], low: [1, 0, 0], empty: [0, 0, 0], fault: [0, 1, 0] }[msg.sim] || [0, 0, 0];
    node.status({ fill: "blue", shape: "ring", text: "ทดสอบ " + (TH[msg.sim] || msg.sim) });
    return [{ payload: { tank: TANK, level: msg.sim, di1: di[0], di2: di[1], di3: di[2], test: true, notify: false }, headers }, null];
}

const a = pick(msg, DI_EMPTY), b = pick(msg, DI_MID), c = pick(msg, DI_FULL);
if (a === null || b === null || c === null) {
    node.status({ fill: "red", shape: "ring", text: "อ่านค่า DI ไม่ได้ – ดู debug 'DI เปลี่ยน'" });
    return [null, { payload: { error: "อ่านรูปแบบค่า DI ไม่ออก", raw: msg.payload } }];
}
const r1 = INVERT ? !a : a, r2 = INVERT ? !b : b, r3 = INVERT ? !c : c;
const level = r1 && r2 && r3 ? "full" : r1 && r2 && !r3 ? "normal" : r1 && !r2 && !r3 ? "low" : !r1 && !r2 && !r3 ? "empty" : "fault";

const now = Date.now();
// แจ้ง debug ทุกครั้งที่สัญญาณ Relay เปลี่ยน (ดูได้ทันที ไม่ต้องรอนิ่ง)
let chg = null;
const rawKey = [r1, r2, r3].map(v => v ? 1 : 0).join("");
if (context.get("rawKey") !== rawKey) {
    context.set("rawKey", rawKey);
    chg = { payload: { time: new Date().toLocaleTimeString("th-TH"), R1_EMPTY_DI1: r1 ? "ติด" : "ดับ", R2_MID_DI2: r2 ? "ติด" : "ดับ",
                       R3_FULL_DI3: r3 ? "ติด" : "ดับ", level: level + " (" + TH[level] + ")", raw: msg.payload } };
}
if (context.get("cand") !== level) { context.set("cand", level); context.set("candAt", now); }
const candAt = context.get("candAt") || now;
let cur = context.get("level"), send = false;
if (level !== cur && now - candAt >= STABLE_MS) { cur = level; context.set("level", cur); send = true; }
if (!send && cur && now - (context.get("sentAt") || 0) >= HEARTBEAT_MS) send = true;

const wait = level !== cur ? " (รอนิ่ง " + Math.max(0, Math.ceil((STABLE_MS - (now - candAt)) / 1000)) + " วิ → " + TH[level] + ")" : "";
const on = v => v ? "●" : "○";
node.status({ fill: cur === "full" ? "blue" : cur === "normal" ? "green" : cur === "low" ? "yellow" : cur === "empty" ? "red" : "grey", shape: "dot",
              text: (cur ? TH[cur] : "เริ่มต้น") + " · R1" + on(r1) + " R2" + on(r2) + " R3" + on(r3) + wait });
if (!send) return [null, chg];
context.set("sentAt", now);
return [{ payload: { tank: TANK, level: cur, di1: r1 ? 1 : 0, di2: r2 ? 1 : 0, di3: r3 ? 1 : 0 }, headers }, chg];

// @ts-nocheck
const ok = msg.statusCode == 200;
const a = msg.payload && msg.payload.alerts && msg.payload.alerts.length ? " · แจ้ง LINE: " + msg.payload.alerts.join(",") : "";
node.status({ fill: ok ? "green" : "red", shape: "dot",
              text: (ok ? "ส่งแล้ว " : "ส่งไม่ได้ HTTP " + msg.statusCode + " ") + new Date().toLocaleTimeString("th-TH") + a });
msg.payload = { ok: ok, http: msg.statusCode, reply: msg.payload };
return msg;
